import{_ as n,l as o,o as e,c as s,v as m,p as E,x as r,d as i,i as h,S as B,b as a}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"雪球结构与定价","description":"","frontmatter":{"title":"雪球结构与定价","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/snowball-pricing.md","filePath":"quant/snowball-pricing.md","lastUpdated":1789023840000}'),p={name:"quant/snowball-pricing.md"};function d(u,t,_,A,c,b){const l=o("Mermaid");return e(),s("div",null,[t[1]||(t[1]=m('<h1 id="雪球结构与定价" tabindex="-1">雪球结构与定价 <a class="header-anchor" href="#雪球结构与定价" aria-label="Permalink to &quot;雪球结构与定价&quot;">​</a></h1><div class="epigraph"><p>雪球是自动赎回的双障碍结构：向上敲出则提前终止并支付票息，向下敲入则激活投资者的下跌参与；价格来自风险中性下对离散观察路径的期望，而不是把票息当无风险利率。</p><footer>—— 障碍期权定价见 Rubinstein–Reiner；离散观察修正见 Broadie, Glasserman and Kou；自动赎回结构的行业分解见结构票据实务</footer></div><p>境内「雪球」通常以证券公司收益凭证或场外期权出现，挂钩中证 500、中证 1000 等指数。投资者在存续期内收取年化票息，代价是卖出一条路径依赖的下跌风险。观察时钟必须写进合约：敲出多为每月（或每隔数个交易日）离散观察，敲入多为每个交易日收盘（近似美式敲入）。若某次敲出观察日收盘价不低于敲出障碍 \\(B_{\\mathrm{out}}\\)（常见为期初的 100%–105%），产品提前结束，返还本金并按持有期支付票息。若存续期内曾触及敲入障碍 \\(B_{\\mathrm{in}}\\)（常见为期初的 70%–85%）且从未敲出，到期结算变为与期末价格挂钩的下跌参与，本金不再完整。若既未敲入也未敲出，到期仍支付本金与票息。本篇写支付分解、数值定价与发行人对冲的希腊值，衔接<a href="/quant/barrier-monitoring">障碍监控频率</a>和<a href="/quant/mc-pricing">蒙特卡洛</a>。适当性、不得宣传保本、柜台衍生品业务规范是约束；不讨论如何把结构改写成规避适当性的包装。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把雪球当成「高票息理财」，漏掉的是嵌入期权的卖方身份。投资者的经济头寸近似：持有零息债券，同时卖出向下敲入看跌，并卖出一串向上敲出的自动赎回权（发行人有权在敲出日终止并支付既定票息）。票息是期权费的分期形式，其高低必须用障碍距离、波动、期限、敲出频率与分红融资来解释。同一 15% 年化，在 \\(B_{\\mathrm{in}}=75\\%\\)、挂钩 500 指数、波动 25% 与在 \\(B_{\\mathrm{in}}=85\\%\\)、波动 18% 上，对应的风险完全不同。问题是在给定条款下计算风险中性价值 \\(V\\)，再与票息反推：发行人卖出凭证的价值应覆盖对冲成本、资本与保证金，而不是把票息与存款利率比。</p><p>支付对路径的依赖使 Black–Scholes 闭式不够用。敲出离散、敲入几乎每日，两种时钟不能都用连续障碍公式。连续监控会高估敲入概率、低估敲出漏检，票息会定错。必须在合约网格上定义触发，再用模拟或带障碍的偏微分数值解。</p><h3 id="三条终局-不是「涨了拿息、跌了亏本」一句" tabindex="-1">三条终局，不是「涨了拿息、跌了亏本」一句 <a class="header-anchor" href="#三条终局-不是「涨了拿息、跌了亏本」一句" aria-label="Permalink to &quot;三条终局，不是「涨了拿息、跌了亏本」一句&quot;">​</a></h3><p>记期初 \\(S_0=1\\)（标准化），期末 \\(S_T\\)，敲出停时 \\(\\tau_{\\mathrm{out}}\\)，敲入示性 \\(K_{\\mathrm{in}}\\)。名义本金为 1 时，投资者支付（现金结算、忽略中间票息的精细日算）可写成：</p><ul><li>若 \\(\\tau_{\\mathrm{out}}\\le T\\)：获得 \\(1+\\) 持有期票息，合约终止；</li><li>若未敲出且 \\(K_{\\mathrm{in}}=0\\)：到期获得 \\(1+\\) 到期票息；</li><li>若未敲出且 \\(K_{\\mathrm{in}}=1\\)：到期获得 \\(S_T\\)（或 \\(S_T/B_{\\mathrm{in}}\\) 等合同约定的参与公式），票息可能部分保留或全无，以条款为准。</li></ul><p>第三支使投资者在敲入后近似做多标的（从 0 到 \\(S_T\\)），也就是把已经卖出的看跌变成了兑现。第一支是自动赎回，切断了剩余期权。定价要把三支的概率与贴现支付加总，不能只用期末分布。</p><p><span class="marginnote">「未敲入未敲出拿全息」看起来像债券，其实是两条障碍都没碰到的路径集合，概率随波动上升而下降。用历史未敲入频率当未来票息兑现率，忽略了条款是在高波动期卖出的：卖出时隐含波动已经把第三支的概率卖贵了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>风险中性定价：</p> \\[V=\\mathbb{E}^{\\mathbb{Q}}\\Big[\\sum_{i} e^{-r t_i} C_i\\,\\mathbf{1}_{\\{\\tau_{\\mathrm{out}}=t_i\\}} + e^{-rT} \\Pi_T\\,\\mathbf{1}_{\\{\\tau_{\\mathrm{out}}\\gt T\\}}\\Big], \\]<p>其中 \\(C_i\\) 为敲出日现金流，\\(\\Pi_T\\) 为未敲出时的到期本金与票息或下跌参与。模拟须在每个敲出日检查 \\(S_{t_i}\\ge B_{\\mathrm{out}}\\)，在每个敲入日检查 \\(S_{t_j}\\le B_{\\mathrm{in}}\\)。步长粗于观察网格会漏敲入；只在敲出日抽样会把每日敲入变成离散敲入，价格偏贵（对发行人）或偏便宜（对投资者）取决于哪一侧。Broadie–Glasserman–Kou 修正可用于把每日观察近似成连续障碍平移，但雪球同时有两种频率，实务上以按交易日网格的蒙特卡洛为主，方差缩减用对偶路径与控制变量。</p><p>波动率不能只用一个 \\(\\sigma\\)。障碍产品对微笑的翼部和期限结构敏感：敲入区域吃的是下跌翼，敲出区域吃的是近点。局部波动可匹配香草切片，但对对冲仍缺随机波动；<a href="/quant/local-stoch-vol">局部随机波动</a>常用于此类路径依赖。校准必须声明：用哪几个到期的香草、是否含分红预测、是否用期货曲线。挂钩指数的定价通常在期货上做对冲，现货指数本身不可交易，基差进入对冲误差。</p><h3 id="票息是方程的未知数-不是输入的收益率" tabindex="-1">票息是方程的未知数，不是输入的收益率 <a class="header-anchor" href="#票息是方程的未知数-不是输入的收益率" aria-label="Permalink to &quot;票息是方程的未知数，不是输入的收益率&quot;">​</a></h3><p>发行人在 \\(t=0\\) 的目标是 \\(V_{\\mathrm{issuer}}\\ge 1-\\mathrm{margin}\\)（或对投资者 \\(V_{\\mathrm{investor}}\\le 1\\)）。给定障碍与期限，解出年化票息 \\(c\\) 使等式成立。\\(c\\) 随 \\(B_{\\mathrm{in}}\\) 上移、随 \\(\\sigma\\) 上升、随期限变长而上升——因为第三支更贵。市场票息高于模型 \\(c\\)，要么发行人加了波动与跳的溢价，要么条款里还有保证金、提前赎回权、或观察日对交易日的精细差别未写入模型。把募集说明书上的「预期年化」当成折现率去算现值，是把卖方期权费当成了无风险收益。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发行人（券商）是投资者的对手方：投资者空头敲入看跌，发行人多头该看跌，Delta 为负，须买入标的或股指期货才能中性，见<a href="/quant/greeks-hedge">希腊值对冲</a>。标的下跌、尚未敲入时，敲入期权更接近生效，发行人 Delta 更负，对冲须加买——表现为「低买」。标的上涨接近敲出时，自动赎回概率升，剩余期权缩短，对冲须减买或转卖——表现为「高卖」。震荡市里这套再平衡可以赚到 Gamma；单边快跌或快涨时，障碍附近的数字风险（digital）使 Delta 跳，复制误差变大。这是定价必须加跳与离散对冲成本的原因，也是下一篇<a href="/quant/snowball-knockin-cascade">敲入踩踏</a>的微观基础。</p><p><span class="marginnote">每日敲入在收盘价上判定时，盘中穿过 \\(B_{\\mathrm{in}}\\) 再收回不算敲入。估值若用连续障碍，会高估敲入、高估投资者亏损概率、从而高估应付票息。合同以收盘（或条款指定的官方指数）为准，模型时钟必须一致。</span></p><h3 id="与香草、普通障碍、自动赎回票据的差别" tabindex="-1">与香草、普通障碍、自动赎回票据的差别 <a class="header-anchor" href="#与香草、普通障碍、自动赎回票据的差别" aria-label="Permalink to &quot;与香草、普通障碍、自动赎回票据的差别&quot;">​</a></h3><p>普通向下敲入看跌没有向上敲出；凤凰、自动赎回票据可能保本或敲出后不再有下跌参与。雪球的危险区是「已敲入、未敲出」：投资者从票息卖方变成指数空头的反面（承担下跌）。香草看跌的 Delta、Vega 光滑；雪球在两条障碍附近各有一层尖峰，且敲出日只有一天有敲出数字风险。对冲限额不能只用到期日的 BS Delta，要按观察日历切换。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>境内雪球是场外合约，受证券公司柜台衍生品与收益凭证规则、投资者适当性、风险揭示约束；私募参与还受《私募证券投资基金运作指引》对场外衍生品的规范。不得向不适当投资者销售，不得按保本或「稳赚票息」宣传。估值与销售材料应区分：模型价值、对手方信用、提前终止权、以及敲入后的最大损失（可亏完名义）。挂钩单股的雪球还叠加停牌、涨跌停与股利，观察日定义更脆。</p><p>不要用历史回测「从未敲入」去替代风险中性概率。不要在障碍附近用粗糙网格给客户报价。不要把发行人内部的对冲 P&amp;L 当成产品对投资者的保证。公开规则下，本篇止于条款如何定价与如何用期货复制，不提供绕开适当性或把雪球拆成未报备收益互换的结构。</p><p><span class="marginnote">保证金与资本会抬高发行人要求的 \\(c\\)，但不改变支付函数。客户看到的票息含中介约束溢价。比较两家券商的票息，须对齐障碍、观察、分红假设与是否可提前Call，否则比较的是不同合约。</span></p>',27)),(e(),E(B,null,{default:r(()=>[h(l,{id:"mermaid-91",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%A0%87%E7%9A%84%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20KO%7B%22%E6%95%B2%E5%87%BA%E8%A7%82%E5%AF%9F%E6%97%A5%20S%20%E2%89%A5%20Bout%3F%22%7D%0A%20%20KO%20--%3E%7C%22%E6%98%AF%22%7C%20CALL%5B%22%E6%8F%90%E5%89%8D%E7%BB%88%E6%AD%A2%EF%BC%9A%E6%9C%AC%E9%87%91%20%2B%20%E6%8C%81%E6%9C%89%E6%9C%9F%E7%A5%A8%E6%81%AF%22%5D%0A%20%20KO%20--%3E%7C%22%E5%90%A6%22%7C%20KI%7B%22%E6%9B%BE%E6%95%B2%E5%85%A5%3F%20%E6%97%A5%E6%94%B6%E7%9B%98%20%E2%89%A4%20Bin%22%7D%0A%20%20KI%20--%3E%20HOLD%5B%22%E7%BB%A7%E7%BB%AD%E5%AD%98%E7%BB%AD%22%5D%0A%20%20HOLD%20--%3E%20S%0A%20%20KI%20--%3E%7C%22%E5%88%B0%E6%9C%9F%E4%BB%8D%E6%9C%AA%E6%95%B2%E5%87%BA%E4%B8%94%E6%9C%AA%E6%95%B2%E5%85%A5%22%7C%20BOND%5B%22%E6%9C%AC%E9%87%91%20%2B%20%E5%88%B0%E6%9C%9F%E7%A5%A8%E6%81%AF%22%5D%0A%20%20KI%20--%3E%7C%22%E5%88%B0%E6%9C%9F%E5%B7%B2%E6%95%B2%E5%85%A5%E6%9C%AA%E6%95%B2%E5%87%BA%22%7C%20PUT%5B%22%E4%B8%8B%E8%B7%8C%E5%8F%82%E4%B8%8E%EF%BC%9A%E6%8C%89%20ST%20%E7%BB%93%E7%AE%97%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a("h2",{id:"小结",tabindex:"-1"},[i("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),t[3]||(t[3]=a("ul",null,[a("li",null,"雪球是离散敲出加接近每日敲入的自动赎回结构；投资者卖出敲入看跌以换票息。"),a("li",null,"定价必须在合约观察网格上做风险中性期望，票息由障碍、波动与时钟反解，不是存款利率。"),a("li",null,"发行人 Delta 为负，对冲表现为下跌加买、临近敲出减仓；障碍处有数字风险。"),a("li",null,"模型须处理两种观察频率、微笑翼部与指数期货基差。"),a("li",null,"销售与存续受场外衍生品适当性约束，不得按保本陈述。"),a("li",null,"出处：障碍期权与离散修正文献；交易所与协会柜台衍生品、收益凭证及适当性公开规则；《私募证券投资基金运作指引》场外衍生品相关条款。")],-1))])}const g=n(p,[["render",d]]);export{f as __pageData,g as default};
